// Write dictionary size (4 bytes)
std::uint32_t size = std::uint32_t(huffman_codes.size());
outfile.write(reinterpret_cast<const std::char*>(&size), sizeof(size));

// Write each character and its code information
for (const auto &pair : huffman_codes) {
    // Write character (1 byte)
    outfile.write(reinterpret_cast<const std::char*>(&pair.first), sizeof(pair.first));

    // Write code length (4 bytes)
    std::uint32_t code_length = std::uint32_t(pair.second.size());
    outfile.write(reinterpret_cast<const std::char*>(&code_length), sizeof(code_length));

    // Write code bits (as bytes)
    const std::string &code = pair.second;
    std::vector<std::uint8_t> code_bytes;
    for (size_t i = 0; i < code.size(); i += 8) {
        std::uint8_t byte = 0;
        for (size_t j = 0; j < 8 && (i + j) < code.size(); ++j) {
            byte = (byte << 1) | (code[i + j] == '1' ? 1 : 0);
        }
        code_bytes.push_back(byte);
    }

    // Write number of bytes needed for the code
    std::uint8_t num_bytes = std::uint8_t(code_bytes.size());
    outfile.write(reinterpret_cast<const std::char*>(&num_bytes), sizeof(num_bytes));

    // Write the code bytes
    outfile.write(reinterpret_cast<const std::char*>(code_bytes.data()), num_bytes);
}
// END_CODE

